import { expect, expectStatus, test, uniqueName } from "../generated/../../fixtures";

test("Vendor names are unique within a tenant", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange: an existing vendor in the member's tenant. The name is unique per run,
  // and the duplicate differs only by letter case, as the scenario requires.
  const member = await apiAs("member");
  const existingName = uniqueName("Acme Freight");
  const existing = await factory.vendor({ as: "member", name: existingName, category: "logistics" });

  // Act: create a vendor whose name matches the existing one ignoring case.
  const response = await member.post("/api/vendors", {
    data: {
      name: existingName.toLowerCase(),
      category: "logistics",
      contact_email: "ops@acmefreight.example",
    },
  });

  // Assert: the response is refused with the documented error code.
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");

  // Assert the stored outcome: the tenant still holds only the original vendor under that name.
  const page = await expectStatus<{ items: { id: string; name: string }[]; total: number }>(
    await member.get("/api/vendors", { params: { q: existingName } }),
    200,
  );
  expect(page.total).toBe(1);
  expect(page.items[0].id).toBe(existing.id);
});
